下面的异步加载偶尔“回调不来”，偶尔在回调里崩溃。指出两处问题并改正：

void UMyLoader::LoadWeaponAsync(TSoftClassPtr<AActor> SoftClass)
{
    TSharedPtr<FStreamableHandle> Handle =
        UAssetManager::GetStreamableManager().RequestAsyncLoad(
            SoftClass.ToSoftObjectPath(),
            FStreamableDelegate::CreateLambda([this, SoftClass]()
            {
                GetWorld()->SpawnActor(SoftClass.Get());
            }));
}

